import {object} from '../document/model.js';
export const motions=['walk','run','sprint','hop','slide'];
const TAU=Math.PI*2;
export function pose(motion,phase){
 if(!motions.includes(motion))throw Error('Choose a supported movement.');phase=((phase%1)+1)%1;const t=phase*TAU,speed=motion==='sprint'?1.5:motion==='run'?1.2:1,flight=motion==='hop'?Math.max(0,Math.sin(t))*.3:motion==='walk'?-.035*Math.sin(t*2):motion==='slide'?0:Math.abs(Math.sin(t))*.11,lean=motion==='sprint'?.27:motion==='run'?.12:motion==='slide'?-.12:0;
 const joints={pelvis:{x:0,y:1.05+flight,z:0},chest:{x:0,y:1.55+flight,z:lean},neck:{x:0,y:1.73+flight,z:lean},head:{x:0,y:1.9+flight,z:lean}};
 for(const [side,sign] of [['L',-1],['R',1]]){const q=t+(sign===1?Math.PI:0),hop=motion==='hop',swing=hop?.1*Math.cos(t):Math.cos(q)*.3*speed,lift=hop?Math.max(0,Math.sin(t))*.12:motion==='slide'?0:Math.max(0,-Math.sin(q))*(motion==='walk'?.16:.36),hip={x:sign*.13,y:1.04+flight,z:0},ankle={x:sign*(motion==='slide'?.19:.13),y:.08+lift+flight*(hop?.4:0),z:motion==='slide'?sign*.4+.08*Math.sin(t):swing};
  const dy=ankle.y-hip.y,dz=ankle.z-hip.z,d=Math.min(.999,Math.hypot(dy,dz)),height=Math.sqrt(Math.max(0,.52*.52-d*d/4)),knee={x:sign*.13,y:(hip.y+ankle.y)/2+dz/(d||1)*height,z:(hip.z+ankle.z)/2-dy/(d||1)*height};joints[side+'Hip']=hip;joints[side+'Knee']=knee;joints[side+'Ankle']=ankle;joints[side+'Toe']={x:ankle.x,y:ankle.y-.035,z:ankle.z+.17};
  const shoulder={x:sign*.25,y:1.57+flight,z:lean},arm=hop?-.5*Math.sin(t):motion==='slide'?.3:-swing*.85;joints[side+'Shoulder']=shoulder;joints[side+'Elbow']={x:sign*.28,y:1.29+flight,z:lean+arm};joints[side+'Hand']={x:sign*.23,y:(motion==='walk'?1.07:1.25)+flight,z:lean+arm+.13};
 }return joints;
}
export function puppetSVG(motion,phase,rotation=90,floor=true){const joints=pose(motion,phase),r=rotation*Math.PI/180,c=Math.cos(r),s=Math.sin(r),project=p=>({x:200+(p.x*c+p.z*s)*140,y:346-p.y*140+(-p.x*s+p.z*c)*15,depth:-p.x*s+p.z*c}),points=Object.fromEntries(Object.entries(joints).map(([k,p])=>[k,project(p)])),bones=[['pelvis','chest'],['chest','neck'],...['L','R'].flatMap(side=>[['pelvis',side+'Hip'],[side+'Hip',side+'Knee'],[side+'Knee',side+'Ankle'],[side+'Ankle',side+'Toe'],['chest',side+'Shoulder'],[side+'Shoulder',side+'Elbow'],[side+'Elbow',side+'Hand']])].sort((a,b)=>(points[a[0]].depth+points[a[1]].depth)-(points[b[0]].depth+points[b[1]].depth));const fmt=v=>Number(v.toFixed(2));
 return `<svg xmlns="http://www.w3.org/2000/svg" width="400" height="400" viewBox="0 0 400 400">${floor?'<path d="M25 359H375" stroke="#777986" stroke-width="2"/>':''}${bones.map(([a,b])=>`<path d="M${fmt(points[a].x)} ${fmt(points[a].y)}L${fmt(points[b].x)} ${fmt(points[b].y)}" stroke="${(points[a].depth+points[b].depth)<0?'#888888':'#cccccc'}" stroke-width="${a==='pelvis'&&b==='chest'?22:10}" stroke-linecap="round"/>`).join('')}${Object.entries(points).filter(([k])=>/Knee|Elbow|Hip|Shoulder|pelvis/.test(k)).map(([,p])=>`<circle cx="${fmt(p.x)}" cy="${fmt(p.y)}" r="6" fill="#bbbbbb"/>`).join('')}<circle cx="${fmt(points.head.x)}" cy="${fmt(points.head.y)}" r="18" fill="#cccccc"/><path d="M${fmt(points.head.x)} ${fmt(points.head.y)}l${fmt(s*12)} ${fmt(c*3)}" stroke="#444444" stroke-width="3" stroke-linecap="round"/></svg>`;
}
export function referenceIndex(reference,time){if(time<reference.start||time>=reference.start+reference.duration)return -1;if(reference.visibleRanges&&!reference.visibleRanges.some(r=>time>=r.start&&time<r.end))return -1;return Math.min(reference.frames.length-1,Math.max(0,Math.floor((time-reference.start)*reference.fps+1e-7)));}
export function referenceLayer(p,{motion='walk',rotation=90,duration=2,start=0,frames}){if(!Array.isArray(frames)||frames.length!==Math.round(duration*p.fps))throw Error('Baked frame count must match cycle length.');return object('image',{name:motion[0].toUpperCase()+motion.slice(1)+' reference · '+duration+'s',width:400,height:400,x:p.width/2-200,y:p.height/2-200,fill:'none',locked:true,opacity:.6,reference:true,exportIncluded:false,referenceFrames:{motion,rotation,start,duration,fps:p.fps,frames}});}
